Below is a **self‑contained** C# console program that demonstrates the most common ways to use generics in .NET:

* A **generic class** (`Pair<T1,T2>`) that can hold two values of any type.
* A **generic method** (`Swap<T>`) that works for any type.
* A **generic method with a constraint** (`Max<T>`) that only accepts types that implement `IComparable<T>`.
* A **generic interface** (`IRepository<T>`) and an implementation (`Repository<T>`) that only works with reference types (`where T : class`).

```csharp
// Program.cs
using System;
using System.Collections.Generic;

namespace GenericsDemo
{
    // --------------------------------------------------------------------
    // 1. Generic class – holds a pair of values of any type
    // --------------------------------------------------------------------
    public class Pair<T1, T2>
    {
        public T1 First  { get; set; }
        public T2 Second { get; set; }

        public Pair(T1 first, T2 second)
        {
            First  = first;
            Second = second;
        }

        public override string ToString() => $"({First}, {Second})";
    }

    // --------------------------------------------------------------------
    // 2. Generic methods
    // --------------------------------------------------------------------
    public static class Utilities
    {
        // Swap two values – works for any type T
        public static void Swap<T>(ref T a, ref T b)
        {
            T temp = a;
            a = b;
            b = temp;
        }

        // Max – only works on types that can be compared (IComparable<T>)
        public static T Max<T>(T a, T b) where T : IComparable<T>
        {
            return a.CompareTo(b) > 0 ? a : b;
        }
    }

    // --------------------------------------------------------------------
    // 3. Generic interface & implementation
    // --------------------------------------------------------------------
    public interface IRepository<T>
    {
        void Add(T item);
        IEnumerable<T> GetAll();
    }

    // Repository works only with reference types (class)
    public class Repository<T> : IRepository<T> where T : class
    {
        private readonly List<T> _items = new List<T>();

        public void Add(T item) => _items.Add(item);
        public IEnumerable<T> GetAll() => _items;
    }

    // --------------------------------------------------------------------
    // 4. A simple entity to store in the repository
    // --------------------------------------------------------------------
    public class Person
    {
        public string Name { get; set; }
        public int    Age  { get; set; }

        public override string ToString() => $"{Name}, {Age}";
    }

    // --------------------------------------------------------------------
    // 5. Demo program
    // --------------------------------------------------------------------
    class Program
    {
        static void Main()
        {
            // --- Generic class ---------------------------------------------
            var pair = new Pair<string, int>("Age", 30);
            Console.WriteLine($"Pair: {pair}");

            // --- Generic method Swap ---------------------------------------
            int x = 5, y = 10;
            Console.WriteLine($"Before swap: x={x}, y={y}");
            Utilities.Swap(ref x, ref y);
            Console.WriteLine($"After swap:  x={x}, y={y}");

            // --- Generic method Max (constraint) ----------------------------
            int max = Utilities.Max(3, 7);
            Console.WriteLine($"Max of 3 and 7 is {max}");

            // --- Generic repository -----------------------------------------
            var repo = new Repository<Person>();
            repo.Add(new Person { Name = "Alice", Age = 28 });
            repo.Add(new Person { Name = "Bob",   Age = 35 });

            Console.WriteLine("\nRepository contents:");
            foreach (var person in repo.GetAll())
                Console.WriteLine(person);
        }
    }
}
```

### What you’ll see when you run it

```
Pair: (Age, 30)
Before swap: x=5, y=10
After swap:  x=10, y=5
Max of 3 and 7 is 7

Repository contents:
Alice, 28
Bob, 35
```

This example covers the essential concepts of generics: type parameters, constraints, and how they enable reusable, type‑safe code. Happy coding!
